    const hasL = Object.prototype.hasOwnProperty.call(local || {}, k),
      hasR = Object.prototype.hasOwnProperty.call(remote || {}, k);
    if (hasL && !hasR) out[k] = structuredClone(local[k]);
    else if (hasR && !hasL) out[k] = structuredClone(remote[k]);
